mapper.sql:
insert into coop_settlement_original_component
    (cash_close_id,topic_id,source_registration_id,payer_registration_id,settlement_id,source_claim_id,payment_fact_id,payment_fact_hash,
     receiver_kind,receiver_member_id,line_type,original_amount,original_order_cash,calculation_version,source_fingerprint)
select #{cashCloseId},#{topicId},#{sourceRegistrationId},#{payerRegistrationId},#{settlementId},#{sourceClaimId},#{paymentFactId},#{paymentFactHash},
       #{receiverKind},#{receiverMemberId},#{lineType},#{originalAmount},#{originalOrderCash},#{calculationVersion},#{sourceFingerprint}
from coop_settlement h join coop_settlement_cash_close c on c.id=h.cash_close_id and c.topic_id=h.topic_id
join coop_settlement_cash_contribution r on r.cash_close_id=c.id and r.registration_id=#{sourceRegistrationId}
join coop_settlement_cash_contribution payer on payer.cash_close_id=c.id and payer.registration_id=#{payerRegistrationId}
join wx_verified_payment_fact pf on pf.id=#{paymentFactId} and pf.fact_hash=#{paymentFactHash}
join cms_registration paid_reg on paid_reg.id=payer.registration_id
where h.id=#{settlementId} and c.id=#{cashCloseId} and c.topic_id=#{topicId}
  and r.payer_registration_id=payer.registration_id and payer.payer_registration_id=payer.registration_id
  and pf.fact_kind='PAYMENT' and binary pf.business_out_trade_no=binary payer.registration_no
  and pf.currency='CNY' and pf.total_fen=#{originalOrderCash}*100 and pf.amount_fen=pf.total_fen
  and binary paid_reg.registration_no=binary pf.business_out_trade_no
  and binary paid_reg.transaction_id=binary pf.transaction_id and paid_reg.wechat_payment_amount*100=pf.amount_fen

mapper.insert:
insert into coop_settlement_original_adjustment
    (cash_close_id,component_id,receipt_id,settlement_id,payer_registration_id,amount,head_was_paid,wallet_debit,debt_amount)
select #{cashCloseId},#{componentId},#{receiptId},#{settlementId},#{payerRegistrationId},#{amount},#{headWasPaid},#{walletDebit},#{debtAmount}
from coop_settlement_original_component c join coop_settlement_refund_receipt r
  on r.cash_close_id=c.cash_close_id and r.payer_registration_id=c.payer_registration_id
where c.id=#{componentId} and r.id=#{receiptId} and c.cash_close_id=#{cashCloseId} and c.settlement_id=#{settlementId}
  and c.payer_registration_id=#{payerRegistrationId}
